class Solution:
    def gardenNoAdj(self, n: int, paths: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n + 1)]
        for x, y in paths:
            adj[x].append(y)
            adj[y].append(x)
        ans = [0] * (n + 1)
        for i in range(1, n + 1):
            used = {ans[j] for j in adj[i]}
            for c in range(1, 5):
                if c not in used:
                    ans[i] = c
                    break
        return ans[1:]

